    private void Login_btnActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_Login_btnActionPerformed
    String email    = jTextField1.getText().trim();
    String password = new String(jPasswordField2.getPassword()).trim();

    if (email.isEmpty() || password.isEmpty()) {
        javax.swing.JOptionPane.showMessageDialog(this,
            "Email dan Password tidak boleh kosong!",
            "Peringatan", javax.swing.JOptionPane.WARNING_MESSAGE);
        return;    
    }//GEN-LAST:event_Login_btnActionPerformed
    try (java.sql.Connection conn = Koneksi.getConnection()) {
        String sql = "SELECT * FROM akun WHERE Email=? AND Password=?";
        java.sql.PreparedStatement ps = conn.prepareStatement(sql);
        ps.setString(1, email);
        ps.setString(2, password);
        java.sql.ResultSet rs = ps.executeQuery();
    
            if (rs.next()) {
                String username = rs.getString("Username"); // ambil username
                String role     = rs.getString("Role");

            // ── Simpan ke session ──────────────────────────
                DataSesi.setLogin(username, role);

                javax.swing.JOptionPane.showMessageDialog(this,
                    "Login berhasil sebagai " + role + "!",
                    "Sukses", javax.swing.JOptionPane.INFORMATION_MESSAGE);

                javax.swing.JFrame frame = new javax.swing.JFrame();
                frame.setDefaultCloseOperation(javax.swing.JFrame.EXIT_ON_CLOSE);

                if (role.equals("Student")) {
                frame.setTitle("Halaman Murid - " + username);
                frame.getContentPane().add(new Murid());
                }
                else if (role.equals("Coach")) {
                frame.setTitle("Halaman Coach - " + username);
                frame.getContentPane().add(new Pengajar());
                }   
                else if (role.equals("Staf")) {
                frame.setTitle("Halaman Staf -" + username);
                frame.getContentPane().add(new Staff());
                }
                else {
    // ✅ Tambahkan ini untuk tangkap role yang tidak dikenali
    System.out.println("DEBUG: Role tidak dikenali = [" + role + "]");
    javax.swing.JOptionPane.showMessageDialog(null, "Role tidak dikenali: " + role);
}
            frame.pack();
            frame.setLocationRelativeTo(null);
            frame.setVisible(true);
            this.dispose();   
            }    
            
        else {
            javax.swing.JOptionPane.showMessageDialog(this,
            "Email atau Password salah!",
            "Login Gagal", javax.swing.JOptionPane.ERROR_MESSAGE);
            }            
    } 
    catch (java.sql.SQLException e) {
        javax.swing.JOptionPane.showMessageDialog(this,
        "Koneksi gagal: " + e.getMessage(),
        "Error", javax.swing.JOptionPane.ERROR_MESSAGE);
                }                     
    }
